# Base's Unicode category by overlay (julia/base/strings/unicode.jl:366 category_code): Base asks
# utf8proc, the C library libjulia links, for a code point's category by a foreigncall of
# utf8proc_category, and a wasm module has no libjulia to call. utf8proc is Julia's own C, its
# commit the one julia/deps/utf8proc.version names at the julia pin (precedent(utf8proc: ...)), so
# the overlay ports its lookup: utf8proc_category reads the category of utf8proc_get_property's
# entry (utf8proc.c:439), which is the two-stage table lookup of unsafe_get_property (utf8proc.c:233).
# Its tables are copied from the pinned utf8proc_data.c, never regenerated: utf8proc_stage1table and
# utf8proc_stage2table entry for entry, their C lines as they stand, and of utf8proc_properties the
# category column alone, each entry's first field, its utf8proc_category_t name read as its value in
# utf8proc.h's enum (the values Base.Unicode's UTF8PROC_CATEGORY_* constants hold). A table is pinned
# by the function that reads it. test/src/unicode.jl re-reads the pinned file and compares every
# entry, and compares the overlay with Base's category_code at every code point. The overlay is
# consistent: natively it computes Base's answer. precedent(dart: the wasm target's @patch libraries,
# sdk/lib/_internal/wasm; gpucompiler: a device's overlays of Base in its method table).

