# utf8proc.c:233 unsafe_get_property: `utf8proc_properties + utf8proc_stage2table[utf8proc_stage1table[uc
# >> 8] + (uc & 0xFF)]`, the entry's index into utf8proc_properties for the pointer C adds it to; uc is
# in 0:0x10ffff, as C asserts
@quarantine pin"precedent(utf8proc: utf8proc.c:233 unsafe_get_property)" "utf8proc's two-stage lookup of a code point's property, the pointer into utf8proc_properties its index there, since a wasm module has no libjulia to call" Base.getindex function utf8proc_unsafe_get_property(uc::Int32)::Int32
    return Int32(getindex(UTF8PROC_STAGE2TABLE, Int(getindex(UTF8PROC_STAGE1TABLE, (uc >> 8) + 1)) + (uc & 0xFF) + 1))
end

# utf8proc.c:242 utf8proc_get_property: utf8proc_properties' first entry for a code point out of range
@quarantine pin"precedent(utf8proc: utf8proc.c:242 utf8proc_get_property)" "utf8proc's property of a code point, utf8proc_properties' first entry out of range, its index there, since a wasm module has no libjulia to call" Base.:< function utf8proc_get_property(uc::Int32)::Int32
    return uc < Int32(0) || uc >= Int32(0x110000) ? Int32(0) : utf8proc_unsafe_get_property(uc)
end

# utf8proc.c:439 utf8proc_category: the category of utf8proc_get_property's entry
@quarantine pin"precedent(utf8proc: utf8proc.c:439 utf8proc_category)" "utf8proc's category of a code point, read from the category column of its property, since a wasm module has no libjulia to call" Base.getindex function utf8proc_category(c::Int32)::Int32
    return Int32(getindex(UTF8PROC_PROPERTIES_CATEGORY, utf8proc_get_property(c) + 1))
end

# Base's own body (julia/base/strings/unicode.jl:366), its foreigncall of utf8proc_category the port
# above: Base passes UInt32(x) where C takes a utf8proc_int32_t, so the same bits as Int32; Base's
# @assume_effects :foldable is not carried over, so no call of it folds
@quarantine pin"julia/base/strings/unicode.jl:366 category_code" "Base's category_code of an Integer is a utf8proc_category foreigncall into libjulia's utf8proc; a wasm module has no libjulia, so utf8proc's lookup over its pinned tables" Base.Unicode.category_code @consistent_overlay METHOD_TABLE function Base.Unicode.category_code(x::Integer)
    return x ≤ 0x10ffff ? utf8proc_category(reinterpret(Int32, UInt32(x))) : Cint(30)
end

# Base's case mappings, its character width and its case predicates by overlay (julia/base/strings/unicode.jl:267
# textwidth, :308 lowercase, :329 uppercase, :354 titlecase, :403 islowercase, :428 isuppercase): Base asks
# utf8proc for each by a foreigncall (utf8proc_charwidth, utf8proc_tolower, utf8proc_toupper, utf8proc_totitle,
# utf8proc_islower, utf8proc_isupper), and a wasm module has no libjulia to call. The ports read the same
# property entry utf8proc_category reads (utf8proc_get_property, above): utf8proc.c's own definitions, each a
# field of that entry, a case mapping's field an index into utf8proc_sequences decoded by seqindex_decode_index
# (utf8proc.c:374). Each further column of utf8proc_properties is a table of its own, read by its one function,
# so a module holds the columns its calls read; the tables are copied from the pinned utf8proc_data.c, never
# regenerated. test/src/unicode_case.jl re-reads the pinned file and compares every entry, and compares each
# overlay with Base's at every code point, natively.

# utf8proc_data.c:1 utf8proc_sequences, its lines 2-1609: the code points of the sequences a property's
# seqindex fields index, a code point past U+FFFF as its two UTF-16 surrogates
