# utf8proc.c:363 seqindex_decode_entry: the code point at a sequence entry, a high surrogate's entry and the
# next decoded as one code point past U+FFFF. Julia differs: C advances the entry pointer it is handed past
# what it read; the port takes the entry's index into utf8proc_sequences and returns the index it ends at
# beside the code point
@quarantine pin"precedent(utf8proc: utf8proc.c:363 seqindex_decode_entry)" "utf8proc's decoding of a sequence entry, since a wasm module has no libjulia to call; Julia differs: the entry pointer C advances is an index into utf8proc_sequences, returned beside the code point" Base.getindex function utf8proc_seqindex_decode_entry(entry::Int)::Tuple{Int32,Int}
    local entry_cp = Int32(getindex(UTF8PROC_SEQUENCES, entry + 1))
    if (entry_cp & Int32(0xF800)) == Int32(0xD800)
        entry = entry + 1
        entry_cp = ((entry_cp & Int32(0x03FF)) << 10) | (Int32(getindex(UTF8PROC_SEQUENCES, entry + 1)) & Int32(0x03FF))
        entry_cp += Int32(0x10000)
    end
    return (entry_cp, entry)
end

# utf8proc.c:374 seqindex_decode_index: the first code point of the sequence at seqindex
@quarantine pin"precedent(utf8proc: utf8proc.c:374 seqindex_decode_index)" "utf8proc's first code point of a sequence, since a wasm module has no libjulia to call" Base.getindex function utf8proc_seqindex_decode_index(seqindex::UInt32)::Int32
    local entry = Int(seqindex)
    return getindex(utf8proc_seqindex_decode_entry(entry), 1)
end

# utf8proc.c:399 utf8proc_tolower: the lowercase mapping's code point, or c where its entry has none
@quarantine pin"precedent(utf8proc: utf8proc.c:399 utf8proc_tolower)" "utf8proc's lowercase of a code point, read from the lowercase_seqindex column of its property, since a wasm module has no libjulia to call" Base.getindex function utf8proc_tolower(c::Int32)::Int32
    local cl = Int32(getindex(UTF8PROC_PROPERTIES_LOWERCASE_SEQINDEX, utf8proc_get_property(c) + 1))
    return cl != Int32(typemax(UInt16)) ? utf8proc_seqindex_decode_index(reinterpret(UInt32, cl)) : c
end

# utf8proc.c:405 utf8proc_toupper: the uppercase mapping's code point, or c where its entry has none
@quarantine pin"precedent(utf8proc: utf8proc.c:405 utf8proc_toupper)" "utf8proc's uppercase of a code point, read from the uppercase_seqindex column of its property, since a wasm module has no libjulia to call" Base.getindex function utf8proc_toupper(c::Int32)::Int32
    local cu = Int32(getindex(UTF8PROC_PROPERTIES_UPPERCASE_SEQINDEX, utf8proc_get_property(c) + 1))
    return cu != Int32(typemax(UInt16)) ? utf8proc_seqindex_decode_index(reinterpret(UInt32, cu)) : c
end

# utf8proc.c:411 utf8proc_totitle: the titlecase mapping's code point, or c where its entry has none
@quarantine pin"precedent(utf8proc: utf8proc.c:411 utf8proc_totitle)" "utf8proc's titlecase of a code point, read from the titlecase_seqindex column of its property, since a wasm module has no libjulia to call" Base.getindex function utf8proc_totitle(c::Int32)::Int32
    local cu = Int32(getindex(UTF8PROC_PROPERTIES_TITLECASE_SEQINDEX, utf8proc_get_property(c) + 1))
    return cu != Int32(typemax(UInt16)) ? utf8proc_seqindex_decode_index(reinterpret(UInt32, cu)) : c
end

# utf8proc.c:417 utf8proc_islower: a code point with a mapping that differs between its cases and no
# lowercase mapping; C's int is a Cint
@quarantine pin"precedent(utf8proc: utf8proc.c:417 utf8proc_islower)" "utf8proc's lowercase predicate, read from its property's case columns, since a wasm module has no libjulia to call" Base.getindex function utf8proc_islower(c::Int32)::Cint
    local p = utf8proc_get_property(c) + 1
    local lowercase_seqindex = getindex(UTF8PROC_PROPERTIES_LOWERCASE_SEQINDEX, p)
    local uppercase_seqindex = getindex(UTF8PROC_PROPERTIES_UPPERCASE_SEQINDEX, p)
    return Cint(lowercase_seqindex != uppercase_seqindex && lowercase_seqindex == typemax(UInt16))
end

# utf8proc.c:423 utf8proc_isupper: a code point with a mapping that differs between its cases, no uppercase
# mapping and a category other than Lt; C's int is a Cint
@quarantine pin"precedent(utf8proc: utf8proc.c:423 utf8proc_isupper)" "utf8proc's uppercase predicate, read from its property's case and category columns, since a wasm module has no libjulia to call" Base.getindex function utf8proc_isupper(c::Int32)::Cint
    local p = utf8proc_get_property(c) + 1
    local lowercase_seqindex = getindex(UTF8PROC_PROPERTIES_LOWERCASE_SEQINDEX, p)
    local uppercase_seqindex = getindex(UTF8PROC_PROPERTIES_UPPERCASE_SEQINDEX, p)
    return Cint(lowercase_seqindex != uppercase_seqindex && uppercase_seqindex == typemax(UInt16) &&
                getindex(UTF8PROC_PROPERTIES_CATEGORY, p) != Base.Unicode.UTF8PROC_CATEGORY_LT)
end

# utf8proc.c:431 utf8proc_charwidth: the charwidth of utf8proc_get_property's entry; C's int is a Cint
@quarantine pin"precedent(utf8proc: utf8proc.c:431 utf8proc_charwidth)" "utf8proc's width of a code point, read from the charwidth column of its property, since a wasm module has no libjulia to call" Base.getindex function utf8proc_charwidth(c::Int32)::Cint
    return Cint(getindex(UTF8PROC_PROPERTIES_CHARWIDTH, utf8proc_get_property(c) + 1))
end

# Base's own body of textwidth (julia/base/strings/unicode.jl:267), and of the case mappings below, each
# foreigncall the port above: ccall converts the character to the UInt32 C takes by
# Base.cconvert (its code point; a malformed Char throws Base's error there, as natively), whose bits C reads
# as a utf8proc_int32_t, and reads C's utf8proc_int32_t result as a UInt32, the same bits
@quarantine pin"julia/base/strings/unicode.jl:267 textwidth" "Base's textwidth of a Char is a utf8proc_charwidth foreigncall into libjulia's utf8proc; a wasm module has no libjulia, so utf8proc's lookup over its pinned tables" Base.Unicode.textwidth @consistent_overlay METHOD_TABLE function Base.Unicode.textwidth(c::Char)
    u = reinterpret(UInt32, c)
    b = bswap(u) # from isascii(c)
    b < 0x7f && return Int(b >= 0x20) # ASCII fast path
    # We can't know a priori how terminals will render invalid UTF8 chars,
    # so we conservatively decide a width of 1.
    (Base.ismalformed(c) || Base.is_overlong_enc(u)) && return 1
    Int(utf8proc_charwidth(reinterpret(Int32, Base.cconvert(UInt32, c))))
end

# Base's bodies of lowercase, uppercase and titlecase (julia/base/strings/unicode.jl:308, :329, :354) are
# overlaid for a Char, Base's T at the call every String's case mapping makes: an overlay of AbstractChar would
# cover the more specific methods of an AnnotatedChar (Base's, unicode.jl:311, :332, :357) and of LinearAlgebra's
# WrapperChar (an unpinned stdlib), which stay theirs and call these with a Char; another AbstractChar keeps
# Base's foreigncall, a located rejection (precedent: src/patch/string.jl's repeat of a Char)
@quarantine pin"julia/base/strings/unicode.jl:308 lowercase" "Base's lowercase of a non-ASCII character is a utf8proc_tolower foreigncall into libjulia's utf8proc; a wasm module has no libjulia, so utf8proc's lookup over its pinned tables; Julia differs: overlaid for a Char, so Base's more specific methods of other characters stay theirs" Base.Unicode.lowercase @consistent_overlay METHOD_TABLE Base.Unicode.lowercase(c::Char) = isascii(c) ? ('A' <= c <= 'Z' ? c + 0x20 : c) :
    Char(reinterpret(UInt32, utf8proc_tolower(reinterpret(Int32, Base.cconvert(UInt32, c)))))

@quarantine pin"julia/base/strings/unicode.jl:329 uppercase" "Base's uppercase of a non-ASCII character is a utf8proc_toupper foreigncall into libjulia's utf8proc; a wasm module has no libjulia, so utf8proc's lookup over its pinned tables; Julia differs: overlaid for a Char, so Base's more specific methods of other characters stay theirs" Base.Unicode.uppercase @consistent_overlay METHOD_TABLE Base.Unicode.uppercase(c::Char) = isascii(c) ? ('a' <= c <= 'z' ? c - 0x20 : c) :
    Char(reinterpret(UInt32, utf8proc_toupper(reinterpret(Int32, Base.cconvert(UInt32, c)))))

@quarantine pin"julia/base/strings/unicode.jl:354 titlecase" "Base's titlecase of a non-ASCII character is a utf8proc_totitle foreigncall into libjulia's utf8proc; a wasm module has no libjulia, so utf8proc's lookup over its pinned tables; Julia differs: overlaid for a Char, so Base's more specific methods of other characters stay theirs" Base.Unicode.titlecase @consistent_overlay METHOD_TABLE Base.Unicode.titlecase(c::Char) = isascii(c) ? ('a' <= c <= 'z' ? c - 0x20 : c) :
    Char(reinterpret(UInt32, utf8proc_totitle(reinterpret(Int32, Base.cconvert(UInt32, c)))))

# Base's own bodies (julia/base/strings/unicode.jl:403 islowercase, :428 isuppercase), each @ccall the port
# above: Base passes UInt32(c), whose bits C reads as a utf8proc_int32_t; Base's @assume_effects :foldable on
# the call is not carried over (a call-site claim no overlay writes), so no call of it folds
@quarantine pin"julia/base/strings/unicode.jl:403 islowercase" "Base's islowercase is a utf8proc_islower foreigncall into libjulia's utf8proc; a wasm module has no libjulia, so utf8proc's predicate over its pinned tables" Base.Unicode.islowercase @consistent_overlay METHOD_TABLE Base.Unicode.islowercase(c::AbstractChar) = Base.ismalformed(c) ? false :
    Bool(utf8proc_islower(reinterpret(Int32, UInt32(c))))

@quarantine pin"julia/base/strings/unicode.jl:428 isuppercase" "Base's isuppercase is a utf8proc_isupper foreigncall into libjulia's utf8proc; a wasm module has no libjulia, so utf8proc's predicate over its pinned tables" Base.Unicode.isuppercase @consistent_overlay METHOD_TABLE Base.Unicode.isuppercase(c::AbstractChar) = Base.ismalformed(c) ? false :
    Bool(utf8proc_isupper(reinterpret(Int32, UInt32(c))))

# Base's grapheme breaks by overlay (julia/base/strings/unicode.jl:794 isgraphemebreak, :801 isgraphemebreak!):
# Base asks utf8proc by a foreigncall of utf8proc_grapheme_break and of utf8proc_grapheme_break_stateful, the
# stateful one passing its Ref{Int32} as the pointer C reads and writes (the foreigncall's argument is
# pointer_from_objref's jl_value_ptr), and a wasm module has no libjulia to call. The overlays port utf8proc's C
# (utf8proc.c:261 grapheme_break_simple, :291 grapheme_break_extended, :345 utf8proc_grapheme_break_stateful, :358
# utf8proc_grapheme_break) over two more columns of utf8proc_properties, each entry's boundclass and
# indic_conjunct_break, copied from the pinned utf8proc_data.c as the category column is, each name read as its
# value in utf8proc.h's enum. C's state pointer is the Ref: C's *state is state[], read and written where C reads
# and writes it, and C's NULL state is `nothing`. test/src/unicode_grapheme.jl re-reads the pinned file's columns
# and compares every entry, and compares the overlays with Base's at every pair of boundclasses and over stateful
# sequences, natively and compiled.

