# utf8proc.c:261 grapheme_break_simple: TR29's rules between a boundclass and the next, GB1 to GB999, C's chain of
# conditionals as it stands, each rule's comment beside its test
@quarantine pin"precedent(utf8proc: utf8proc.c:261 grapheme_break_simple)" "utf8proc's grapheme break between two boundclasses without state, since a wasm module has no libjulia to call" Base.:(==) function grapheme_break_simple(lbc::Int32, tbc::Int32)::Bool
    return (lbc == UTF8PROC_BOUNDCLASS_START) ? true :                                  # GB1
        (lbc == UTF8PROC_BOUNDCLASS_CR &&                                               # GB3
         tbc == UTF8PROC_BOUNDCLASS_LF) ? false :                                       # ---
        (lbc >= UTF8PROC_BOUNDCLASS_CR && lbc <= UTF8PROC_BOUNDCLASS_CONTROL) ? true :  # GB4
        (tbc >= UTF8PROC_BOUNDCLASS_CR && tbc <= UTF8PROC_BOUNDCLASS_CONTROL) ? true :  # GB5
        (lbc == UTF8PROC_BOUNDCLASS_L &&                                                # GB6
         (tbc == UTF8PROC_BOUNDCLASS_L ||                                               # ---
          tbc == UTF8PROC_BOUNDCLASS_V ||                                               # ---
          tbc == UTF8PROC_BOUNDCLASS_LV ||                                              # ---
          tbc == UTF8PROC_BOUNDCLASS_LVT)) ? false :                                    # ---
        ((lbc == UTF8PROC_BOUNDCLASS_LV ||                                              # GB7
          lbc == UTF8PROC_BOUNDCLASS_V) &&                                              # ---
         (tbc == UTF8PROC_BOUNDCLASS_V ||                                               # ---
          tbc == UTF8PROC_BOUNDCLASS_T)) ? false :                                      # ---
        ((lbc == UTF8PROC_BOUNDCLASS_LVT ||                                             # GB8
          lbc == UTF8PROC_BOUNDCLASS_T) &&                                              # ---
         tbc == UTF8PROC_BOUNDCLASS_T) ? false :                                        # ---
        (tbc == UTF8PROC_BOUNDCLASS_EXTEND ||                                           # GB9
         tbc == UTF8PROC_BOUNDCLASS_ZWJ ||                                              # ---
         tbc == UTF8PROC_BOUNDCLASS_SPACINGMARK ||                                      # GB9a
         lbc == UTF8PROC_BOUNDCLASS_PREPEND) ? false :                                  # GB9b
        (lbc == UTF8PROC_BOUNDCLASS_E_ZWG &&                                            # GB11 (requires additional handling below)
         tbc == UTF8PROC_BOUNDCLASS_EXTENDED_PICTOGRAPHIC) ? false :                    # ----
        (lbc == UTF8PROC_BOUNDCLASS_REGIONAL_INDICATOR &&                               # GB12/13 (requires additional handling below)
         tbc == UTF8PROC_BOUNDCLASS_REGIONAL_INDICATOR) ? false :                       # ----
        true                                                                            # GB999
end

# utf8proc.c:291 grapheme_break_extended: with a state, the boundclass and Indic_Conjunct_Break it carries stand
# for the last code point's (GB9c, GB11, GB12/13), its first byte the boundclass and its second the
# indic_conjunct_break, and it is updated with the next's; without one (C's NULL), grapheme_break_simple
@quarantine pin"precedent(utf8proc: utf8proc.c:291 grapheme_break_extended)" "utf8proc's grapheme break between two code points' boundclasses and Indic_Conjunct_Break values, reading and updating the state when there is one, since a wasm module has no libjulia to call; Julia differs: C's state pointer is a Ref, *state its [], and NULL is nothing" Base.:(==) function grapheme_break_extended(lbc::Int32, tbc::Int32, licb::Int32, ticb::Int32, state::Union{Nothing,Ref{Int32}})::Bool
    if state !== nothing
        local state_bc::Int32, state_icb::Int32  # boundclass and indic_conjunct_break state
        if state[] == Int32(0)  # state initialization
            state_bc = lbc
            state_icb = licb == UTF8PROC_INDIC_CONJUNCT_BREAK_CONSONANT ? licb : UTF8PROC_INDIC_CONJUNCT_BREAK_NONE
        else  # lbc and licb are already encoded in *state
            state_bc = state[] & Int32(0xff)  # 1st byte of state is bound class
            state_icb = state[] >> 8          # 2nd byte of state is indic conjunct break
        end

        local break_permitted::Bool = grapheme_break_simple(state_bc, tbc) &&
            !(state_icb == UTF8PROC_INDIC_CONJUNCT_BREAK_LINKER &&
              ticb == UTF8PROC_INDIC_CONJUNCT_BREAK_CONSONANT)  # GB9c

        # Special support for GB9c.  Don't break between two consonants
        # separated 1+ linker characters and 0+ extend characters in any order.
        # After a consonant, we enter LINKER state after at least one linker.
        if ticb == UTF8PROC_INDIC_CONJUNCT_BREAK_CONSONANT ||
           state_icb == UTF8PROC_INDIC_CONJUNCT_BREAK_CONSONANT ||
           state_icb == UTF8PROC_INDIC_CONJUNCT_BREAK_EXTEND
            state_icb = ticb
        elseif state_icb == UTF8PROC_INDIC_CONJUNCT_BREAK_LINKER
            state_icb = ticb == UTF8PROC_INDIC_CONJUNCT_BREAK_EXTEND ?
                        UTF8PROC_INDIC_CONJUNCT_BREAK_LINKER : ticb
        end

        # Special support for GB 12/13 made possible by GB999. After two RI
        # class codepoints we want to force a break. Do this by resetting the
        # second RI's bound class to UTF8PROC_BOUNDCLASS_OTHER, to force a break
        # after that character according to GB999 (unless of course such a break is
        # forbidden by a different rule such as GB9).
        if state_bc == tbc && tbc == UTF8PROC_BOUNDCLASS_REGIONAL_INDICATOR
            state_bc = UTF8PROC_BOUNDCLASS_OTHER
        # Special support for GB11 (emoji extend* zwj / emoji)
        elseif state_bc == UTF8PROC_BOUNDCLASS_EXTENDED_PICTOGRAPHIC
            if tbc == UTF8PROC_BOUNDCLASS_EXTEND  # fold EXTEND codepoints into emoji
                state_bc = UTF8PROC_BOUNDCLASS_EXTENDED_PICTOGRAPHIC
            elseif tbc == UTF8PROC_BOUNDCLASS_ZWJ
                state_bc = UTF8PROC_BOUNDCLASS_E_ZWG  # state to record emoji+zwg combo
            else
                state_bc = tbc
            end
        else
            state_bc = tbc
        end

        state[] = state_bc + (state_icb << 8)
        return break_permitted
    else
        return grapheme_break_simple(lbc, tbc)
    end
end

# utf8proc.c:345 utf8proc_grapheme_break_stateful: the boundclasses and Indic_Conjunct_Break values of the two code
# points' properties, each read from its column of utf8proc_get_property's entry
@quarantine pin"precedent(utf8proc: utf8proc.c:345 utf8proc_grapheme_break_stateful)" "utf8proc's grapheme break between two code points, reading and updating the state when there is one, since a wasm module has no libjulia to call; Julia differs: C's state pointer is a Ref, and NULL is nothing" Base.getindex function utf8proc_grapheme_break_stateful(c1::Int32, c2::Int32, state::Union{Nothing,Ref{Int32}})::Bool
    local p1 = utf8proc_get_property(c1)
    local p2 = utf8proc_get_property(c2)
    return grapheme_break_extended(Int32(getindex(UTF8PROC_PROPERTIES_BOUNDCLASS, p1 + 1)),
                                   Int32(getindex(UTF8PROC_PROPERTIES_BOUNDCLASS, p2 + 1)),
                                   Int32(getindex(UTF8PROC_PROPERTIES_INDIC_CONJUNCT_BREAK, p1 + 1)),
                                   Int32(getindex(UTF8PROC_PROPERTIES_INDIC_CONJUNCT_BREAK, p2 + 1)),
                                   state)
end

# utf8proc.c:358 utf8proc_grapheme_break: the stateful break with no state, C's NULL
@quarantine pin"precedent(utf8proc: utf8proc.c:358 utf8proc_grapheme_break)" "utf8proc's grapheme break between two code points without state, since a wasm module has no libjulia to call; Julia differs: C's NULL state is nothing" Core.nothing function utf8proc_grapheme_break(c1::Int32, c2::Int32)::Bool
    return utf8proc_grapheme_break_stateful(c1, c2, nothing)
end

# Base's own bodies (julia/base/strings/unicode.jl:794, :801), each foreigncall the port above: the foreigncall
# converts each AbstractChar argument by cconvert(UInt32, c), convert, to the bits C takes as a utf8proc_int32_t,
# and passes the Ref{Int32} as the pointer to its value, which the port reads and writes as state[]
@quarantine pin"julia/base/strings/unicode.jl:794 isgraphemebreak" "Base's isgraphemebreak is a utf8proc_grapheme_break foreigncall into libjulia's utf8proc; a wasm module has no libjulia, so utf8proc's C over its pinned tables" Base.Unicode.isgraphemebreak @consistent_overlay METHOD_TABLE Base.Unicode.isgraphemebreak(c1::AbstractChar, c2::AbstractChar) =
    Base.ismalformed(c1) || Base.ismalformed(c2) ||
    utf8proc_grapheme_break(reinterpret(Int32, convert(UInt32, c1)), reinterpret(Int32, convert(UInt32, c2)))

@quarantine pin"julia/base/strings/unicode.jl:801 isgraphemebreak!" "Base's isgraphemebreak! is a utf8proc_grapheme_break_stateful foreigncall into libjulia's utf8proc, its Ref{Int32} passed as a pointer (pointer_from_objref's jl_value_ptr); a wasm module has no libjulia, so utf8proc's C over its pinned tables, the Ref read and written as C reads and writes the pointer" Base.Unicode.isgraphemebreak! @consistent_overlay METHOD_TABLE @inline function Base.Unicode.isgraphemebreak!(state::Ref{Int32}, c1::AbstractChar, c2::AbstractChar)
    if Base.ismalformed(c1) || Base.ismalformed(c2)
        state[] = 0
        return true
    end
    return utf8proc_grapheme_break_stateful(reinterpret(Int32, convert(UInt32, c1)), reinterpret(Int32, convert(UInt32, c2)), state)
end

# Base's _isoperator by overlay (julia/base/show.jl:1577): Base passes the name as a Cstring to libjulia's
# jl_is_operator (julia/src/ast.c:992), which interns it as a flisp symbol and applies the flisp parser's
# operator? to it, and a wasm module has no libjulia and no flisp to call. The port follows the C and the
# parser's own definitions: operator? (julia-parser.scm line 142) is a SuffSet of the parser's operator
# list, membership after maybe-strip-op-suffix (line 66), whose strip-op-suffix is the C builtin
# fl_julia_strip_op_suffix (julia/src/flisp/julia_extensions.c:245), walking the name's characters by
# u8_nextchar (julia/src/support/utf8.c:269) to the first jl_op_suffix_char (julia_extensions.c:163). The
# operator lists are julia-parser.scm's definitions at the julia pin, their symbols copied as written and
# built as the parser builds them, when WasmTarget loads. The overlay is consistent: natively it computes
# Base's answer, which test/src/julia_parser_ops.jl compares at every operator the pinned julia-parser.scm's
# defines name, its dotted and suffixed forms and every character to U+FFFF, and test/src/unicode.jl
# re-reads the C tables copied here from their pinned files.

# julia-parser.scm's operator lists at the julia pin, each definition copied from its own define and pinned at
# that line (julia/src/julia-parser.scm, a unit of JULIA_FILES), a |...| symbol read as femtolisp reads it; the
# derived lists (prec-names, no-suffix?, operators) built from them by the parser's own rules when WasmTarget loads

# femtolisp's add-dots: each operator, then each with a `.` before it (its elementwise form)
@quarantine pin"julia/src/julia-parser.scm:4 add-dots" "the femtolisp parser makes each operator's dotted form by add-dots; its tables are built by it" Base.vcat add_dots(ops::Vector{String})::Vector{String} =
    vcat(ops, String["." * op for op in ops])

