# julia_extensions.c:67 is_wc_cat_id_start: whether a code point of category cat may start an identifier:
# a letter, Nl, Sc, an So but an arrow, U+FFFC, U+FFFD, U+233F or U+00A6, and the C's allowlists of math
# symbols, nabla and partial variants, sub- and superscript +-=(), angles, Other_ID_Start and the bold and
# double-struck digits, each as C writes it. Julia differs: C's int is a Bool
@quarantine pin"julia/src/flisp/julia_extensions.c:67 is_wc_cat_id_start" "whether a code point of a category may start an identifier, as libjulia's flisp extension answers it; a wasm module has no libjulia to call; Julia differs: C's int is a Bool" Base.:(==) function is_wc_cat_id_start(wc::UInt32, cat::Int32)::Bool
    return (cat == Base.Unicode.UTF8PROC_CATEGORY_LU || cat == Base.Unicode.UTF8PROC_CATEGORY_LL ||
            cat == Base.Unicode.UTF8PROC_CATEGORY_LT || cat == Base.Unicode.UTF8PROC_CATEGORY_LM ||
            cat == Base.Unicode.UTF8PROC_CATEGORY_LO || cat == Base.Unicode.UTF8PROC_CATEGORY_NL ||
            cat == Base.Unicode.UTF8PROC_CATEGORY_SC ||  # allow currency symbols
            # other symbols, but not arrows or replacement characters
            (cat == Base.Unicode.UTF8PROC_CATEGORY_SO && !(wc >= 0x2190 && wc <= 0x21FF) &&
             wc != 0xfffc && wc != 0xfffd &&
             wc != 0x233f &&  # notslash
             wc != 0x00a6) || # broken bar

            # math symbol (category Sm) allowlist
            (wc >= 0x2140 && wc <= 0x2a1c &&
             ((wc >= 0x2140 && wc <= 0x2144) || # ⅀, ⅁, ⅂, ⅃, ⅄
              wc == 0x223f || wc == 0x22be || wc == 0x22bf || # ∿, ⊾, ⊿
              wc == 0x22a4 || wc == 0x22a5 ||   # ⊤ ⊥

              (wc >= 0x2200 && wc <= 0x2233 &&
               (wc == 0x2202 || wc == 0x2205 || wc == 0x2206 || # ∂, ∅, ∆
                wc == 0x2207 || wc == 0x220e || wc == 0x220f || # ∇, ∎, ∏
                wc == 0x2200 || wc == 0x2203 || wc == 0x2204 || # ∀, ∃, ∄
                wc == 0x2210 || wc == 0x2211 || # ∐, ∑
                wc == 0x221e || wc == 0x221f || # ∞, ∟
                wc >= 0x222b)) || # ∫, ∬, ∭, ∮, ∯, ∰, ∱, ∲, ∳

              (wc >= 0x22c0 && wc <= 0x22c3) ||  # N-ary big ops: ⋀, ⋁, ⋂, ⋃
              (wc >= 0x25F8 && wc <= 0x25ff) ||  # ◸, ◹, ◺, ◻, ◼, ◽, ◾, ◿

              (wc >= 0x266f &&
               (wc == 0x266f || wc == 0x27d8 || wc == 0x27d9 || # ♯, ⟘, ⟙
                (wc >= 0x27c0 && wc <= 0x27c1) ||  # ⟀, ⟁
                (wc >= 0x29b0 && wc <= 0x29b4) ||  # ⦰, ⦱, ⦲, ⦳, ⦴
                (wc >= 0x2a00 && wc <= 0x2a06) ||  # ⨀, ⨁, ⨂, ⨃, ⨄, ⨅, ⨆
                (wc >= 0x2a09 && wc <= 0x2a16) ||  # ⨉, ⨊, ⨋, ⨌, ⨍, ⨎, ⨏, ⨐, ⨑, ⨒, ⨓, ⨔, ⨕, ⨖
                wc == 0x2a1b || wc == 0x2a1c)))) || # ⨛, ⨜

            (wc >= 0x1d6c1 && # variants of \nabla and \partial
             (wc == 0x1d6c1 || wc == 0x1d6db ||
              wc == 0x1d6fb || wc == 0x1d715 ||
              wc == 0x1d735 || wc == 0x1d74f ||
              wc == 0x1d76f || wc == 0x1d789 ||
              wc == 0x1d7a9 || wc == 0x1d7c3)) ||

            # super- and subscript +-=()
            (wc >= 0x207a && wc <= 0x207e) ||
            (wc >= 0x208a && wc <= 0x208e) ||

            # angle symbols
            (wc >= 0x2220 && wc <= 0x2222) || # ∠, ∡, ∢
            (wc >= 0x299b && wc <= 0x29af) || # ⦛, ⦜, ⦝, ⦞, ⦟, ⦠, ⦡, ⦢, ⦣, ⦤, ⦥, ⦦, ⦧, ⦨, ⦩, ⦪, ⦫, ⦬, ⦭, ⦮, ⦯

            # Other_ID_Start
            wc == 0x2118 || wc == 0x212E || # ℘, ℮
            (wc >= 0x309B && wc <= 0x309C) || # katakana-hiragana sound marks

            # bold-digits and double-struck digits
            (wc >= 0x1D7CE && wc <= 0x1D7E1)) # 𝟎 through 𝟗 (inclusive), 𝟘 through 𝟡 (inclusive)
end

# julia_extensions.c:127 jl_id_start_char: whether a code point may start an identifier: an ASCII letter or
# `_`; none other below U+00A1 or past U+10FFFF; U+1F8B2; else is_wc_cat_id_start of its category (utf8proc's,
# the port above). Julia differs: C's int is a Cint
@quarantine pin"julia/src/flisp/julia_extensions.c:127 jl_id_start_char" "whether a code point may start an identifier, as libjulia's flisp extension answers it; a wasm module has no libjulia to call" Base.Cint function jl_id_start_char(wc::UInt32)::Cint
    if (wc >= UInt32('A') && wc <= UInt32('Z')) || (wc >= UInt32('a') && wc <= UInt32('z')) || wc == UInt32('_')
        return Cint(1)
    end
    if wc < 0xA1 || wc > 0x10ffff
        return Cint(0)
    end
    # "Rightwards Arrow with Lower Hook"
    if wc == 0x1f8b2
        return Cint(1)
    end
    return Cint(is_wc_cat_id_start(wc, utf8proc_category(reinterpret(Int32, wc))))
end

# julia_extensions.c:139 jl_id_char: whether a code point may continue an identifier: an ASCII letter, digit,
# `_` or `!`; none other below U+00A1 or past U+10FFFF; one that may start one; a category Mn, Mc, Nd, Pc, Sk,
# Me or No; a prime; U+1F8B2. Julia differs: C's int is a Cint
@quarantine pin"julia/src/flisp/julia_extensions.c:139 jl_id_char" "whether a code point may continue an identifier, as libjulia's flisp extension answers it; a wasm module has no libjulia to call" Base.Cint function jl_id_char(wc::UInt32)::Cint
    if (wc >= UInt32('A') && wc <= UInt32('Z')) || (wc >= UInt32('a') && wc <= UInt32('z')) || wc == UInt32('_') ||
        (wc >= UInt32('0') && wc <= UInt32('9')) || wc == UInt32('!')
        return Cint(1)
    end
    if wc < 0xA1 || wc > 0x10ffff
        return Cint(0)
    end
    local cat = utf8proc_category(reinterpret(Int32, wc))
    is_wc_cat_id_start(wc, cat) && return Cint(1)
    if cat == Base.Unicode.UTF8PROC_CATEGORY_MN || cat == Base.Unicode.UTF8PROC_CATEGORY_MC ||
        cat == Base.Unicode.UTF8PROC_CATEGORY_ND || cat == Base.Unicode.UTF8PROC_CATEGORY_PC ||
        cat == Base.Unicode.UTF8PROC_CATEGORY_SK || cat == Base.Unicode.UTF8PROC_CATEGORY_ME ||
        cat == Base.Unicode.UTF8PROC_CATEGORY_NO ||
        # primes (single, double, triple, their reverses, and quadruple)
        (wc >= 0x2032 && wc <= 0x2037) || (wc == 0x2057) ||
        # "Rightwards Arrow with Lower Hook"
        wc == 0x1f8b2
        return Cint(1)
    end
    return Cint(0)
end

