@quarantine pin"julia/base/show.jl:1542 is_id_start_char" "Base's is_id_start_char is a jl_id_start_char foreigncall into libjulia's flisp extensions; a wasm module has no libjulia, so the port of jl_id_start_char" Base.is_id_start_char @consistent_overlay METHOD_TABLE Base.is_id_start_char(c::AbstractChar) =
    jl_id_start_char(Base.cconvert(UInt32, c)) != 0

